using Microsoft.Data.Sqlite;

namespace TwelveLegions.Server;

// Internal contracts only. Production facts are generated by authorized
// tournament transitions, never supplied by an HTTP fact submission endpoint.
internal sealed record L12TournamentCheckInPlanFact(int Revision, DateTimeOffset? StartAt,
    int CheckInMinutes, DateTimeOffset? OpensAt, DateTimeOffset RecordedAt, string ActorId, string CorrelationId);
internal sealed record L12TournamentCheckInStartFact(DateTimeOffset EffectiveAt, DateTimeOffset RecordedAt,
    int PlanRevision, string Source, string? ActorId, string CorrelationId);
internal sealed record L12TournamentCheckInFacts(int RuleVersion,
    IReadOnlyList<L12TournamentCheckInPlanFact> Plans, L12TournamentCheckInStartFact? Start);
internal sealed record L12TournamentReputationFact(string Id, string TournamentId, string AccountId,
    string Kind, DateTimeOffset EffectiveAt, string? RevokesEventId = null);
internal sealed record L12TournamentReputationProjection(int Score, long Revision, DateTimeOffset AsOf,
    DateTimeOffset? LastViolationAt, DateTimeOffset? NextRecoveryAt);
internal sealed record L12TournamentReputationOperation(bool Applied, bool AlreadyApplied,
    string? Exemption, L12TournamentReputationProjection Projection);
public sealed record L12TournamentReputationHistoryItemView(string Id, int Sequence, string TournamentId,
    string TournamentName, string Kind, DateTimeOffset EffectiveAt, DateTimeOffset RecordedAt,
    string Assessment, int? EffectiveScoreChange, string? RevokesEventId, string? Exemption);
public sealed record L12TournamentReputationPageView(int RuleVersion, int Score, string Qualification,
    DateTimeOffset AsOf, long Revision, DateTimeOffset? NextRecoveryAt, int Page, int PageSize,
    int Total, IReadOnlyList<L12TournamentReputationHistoryItemView> Items);

public sealed record L12TournamentReputationCorrectionProjection(int Score, DateTimeOffset? LastViolationAt,
    DateTimeOffset? NextRecoveryAt);
public sealed record L12TournamentReputationRevokePreview(string AccountId, string EventId, string TournamentId,
    long TournamentVersion, long PlatformVersion, long ReputationRevision, bool AlreadyRevoked,
    L12TournamentReputationCorrectionProjection Before, L12TournamentReputationCorrectionProjection After);
public sealed record L12TournamentReputationRevokeResult(bool Applied, bool AlreadyApplied, int Score,
    long Revision, DateTimeOffset? NextRecoveryAt);
internal sealed record L12TournamentReputationRevokePayload(string AccountId, string EventId, string Reason,
    long ExpectedTournamentVersion, long ExpectedReputationRevision);

public sealed partial class L12PlatformStore
{
    private const int TournamentReputationRuleVersion = 1;
    private const int TournamentReputationSchemaVersion = 11;
    private static readonly TimeSpan TournamentReputationRecoveryPeriod = TimeSpan.FromDays(7);

    private sealed class TournamentCheckInPlanRow
    {
        public int Revision { get; set; }
        public DateTimeOffset? StartAt { get; set; }
        public int CheckInMinutes { get; set; }
        public DateTimeOffset? OpensAt { get; set; }
        public DateTimeOffset RecordedAt { get; set; }
        public string ActorId { get; set; } = string.Empty;
        public string CorrelationId { get; set; } = string.Empty;
    }

    private sealed class TournamentCheckInStartRow
    {
        public DateTimeOffset EffectiveAt { get; set; }
        public DateTimeOffset RecordedAt { get; set; }
        public int PlanRevision { get; set; }
        public string Source { get; set; } = string.Empty;
        public string? ActorId { get; set; }
        public string CorrelationId { get; set; } = string.Empty;
    }

    private sealed record TournamentReputationSource(bool FormalSeat, DateTimeOffset? CheckInStartedAt,
        string RootId, string Kind, string? MatchId = null, int? Round = null, DateTimeOffset? Deadline = null);

    private sealed record TournamentReputationEventRow(string Id, string TournamentId, int RuleVersion,
        string Kind, DateTimeOffset EffectiveAt, DateTimeOffset RecordedAt, int Penalty,
        bool FormalSeat, DateTimeOffset? CheckInStartedAt, string? Exemption,
        string? RevokesEventId, string ActorId, string CorrelationId, TournamentReputationSource? Source = null);

    private sealed class TournamentReputationStateRow
    {
        public int RuleVersion { get; set; } = TournamentReputationRuleVersion;
        public long Revision { get; set; }
        public List<TournamentReputationEventRow> Events { get; set; } = [];
        // This is a validated checkpoint, not a second scoring authority. Reads
        // derive time recovery without updating it or materializing timer events.
        public int Score { get; set; } = 100;
        public DateTimeOffset ProjectedAt { get; set; }
        public DateTimeOffset? LastViolationAt { get; set; }
        public DateTimeOffset? NextRecoveryAt { get; set; }
    }

    private static void InitializeTournamentReputationSchema(SqliteConnection connection)
    {
        var version = ReadExistingStorageSchemaVersion(connection);
        if (version == TournamentReputationSchemaVersion) return;
        if (version != AccountRankedRestrictionSchemaVersion)
            throw new L12PlatformStorageIncompatibleException("赛事信誉迁移需要完整 schema 10 数据库");
        using var transaction = connection.BeginTransaction(deferred: false);
        if (ReadSnapshot(connection, transaction) is { } stored)
            DeserializeDataAndValidate(ValidateSnapshot(stored));
        // Optional new facts only: no old tournament is enabled or backfilled.
        SetStorageSchemaVersion(connection, transaction, TournamentReputationSchemaVersion);
        transaction.Commit();
    }

    private static void InitializeTournamentReputationPolicy(TournamentRow row, string actorId, string correlationId)
    {
        row.ReputationRuleVersion = TournamentReputationRuleVersion;
        AppendTournamentCheckInPlan(row, row.CreatedAt, actorId, correlationId);
    }

    private static void AppendTournamentCheckInPlan(TournamentRow row, DateTimeOffset now,
        string actorId, string correlationId)
    {
        if (row.ReputationRuleVersion != TournamentReputationRuleVersion) return;
        now = now.ToUniversalTime();
        var planned = row.StartAt?.ToUniversalTime().AddMinutes(-row.CheckInMinutes);
        // A newly published plan cannot create a penalty boundary in its past.
        if (planned < now) planned = now;
        row.CheckInPlans.Add(new()
        {
            Revision = row.CheckInPlans.Count + 1, StartAt = row.StartAt?.ToUniversalTime(),
            CheckInMinutes = row.CheckInMinutes, OpensAt = planned, RecordedAt = now,
            ActorId = actorId, CorrelationId = string.IsNullOrWhiteSpace(correlationId)
                ? $"tournament:{row.Id}:plan:{row.CheckInPlans.Count + 1}" : correlationId,
        });
    }

    private static void CaptureDueTournamentCheckInStart(TournamentRow row, DateTimeOffset now)
    {
        if (row.ReputationRuleVersion != TournamentReputationRuleVersion || row.Status != "registration" || row.CheckInStart is not null
            || row.CheckInPlans.LastOrDefault() is not { OpensAt: { } opensAt } plan || now < opensAt) return;
        row.CheckInStart = new()
        {
            EffectiveAt = opensAt, RecordedAt = now.ToUniversalTime(), PlanRevision = plan.Revision,
            Source = "scheduled", CorrelationId = plan.CorrelationId,
        };
    }

    private static void CaptureTournamentCheckInStart(TournamentRow row, DateTimeOffset now, string source,
        string? actorId, string? correlationId)
    {
        if (row.ReputationRuleVersion != TournamentReputationRuleVersion || row.CheckInStart is not null) return;
        CaptureDueTournamentCheckInStart(row, now);
        row.CheckInStart ??= new()
        {
            EffectiveAt = now.ToUniversalTime(), RecordedAt = now.ToUniversalTime(),
            PlanRevision = row.CheckInPlans.Count, Source = source, ActorId = actorId,
            CorrelationId = string.IsNullOrWhiteSpace(correlationId)
                ? $"tournament:{row.Id}:start:{row.Version}" : correlationId,
        };
    }

    internal L12TournamentCheckInFacts TournamentCheckInFacts(L12AccountView actor, string tournamentId)
    {
        lock (_gate)
        {
            var row = _data.Tournaments.FirstOrDefault(item => item.Id == tournamentId)
                ?? throw new KeyNotFoundException("赛事不存在");
            EnsurePermission(actor, L12Permission.TournamentsRead);
            RequireActiveTournamentAccount(actor);
            if (!IsConfiguredStaff(row, actor.Id) && !CanGloballyAccessTournaments(actor))
                throw new L12TournamentScopeException("当前账号不可读取本赛事签到事实");
            return new(row.ReputationRuleVersion, row.CheckInPlans.Select(plan =>
                new L12TournamentCheckInPlanFact(plan.Revision, plan.StartAt, plan.CheckInMinutes,
                    plan.OpensAt, plan.RecordedAt, plan.ActorId, plan.CorrelationId)).ToArray(),
                row.CheckInStart is not { } start ? null : new(start.EffectiveAt, start.RecordedAt,
                    start.PlanRevision, start.Source, start.ActorId, start.CorrelationId));
        }
    }

    internal L12TournamentReputationProjection TournamentReputationProjection(L12AccountView actor,
        string accountId, DateTimeOffset utcNow)
    {
        if (actor.Id != accountId) EnsurePermission(actor, L12Permission.AdminAccountsRead);
        lock (_gate)
        {
            var account = AccountById(accountId) ?? throw new KeyNotFoundException("账号不存在");
            return ProjectTournamentReputation(account.TournamentReputation, utcNow.ToUniversalTime());
        }
    }

    internal L12TournamentReputationPageView ReadOwnTournamentReputation(string? authorization,
        int page = 1, int pageSize = 20, long? expectedRevision = null)
        => ReadPrivateTournamentReputation(authorization, null, false, page, pageSize, expectedRevision);

    internal L12TournamentReputationPageView ReadAccountTournamentReputation(string? authorization,
        string accountId, int page = 1, int pageSize = 20, long? expectedRevision = null)
        => ReadPrivateTournamentReputation(authorization, accountId, true, page, pageSize, expectedRevision);

    private L12TournamentReputationPageView ReadPrivateTournamentReputation(string? authorization,
        string? accountId, bool administrator, int page, int pageSize, long? expectedRevision)
    {
        lock (_gate)
        {
            // Reuse the original authenticator while owning the same Store lock:
            // its staged/current-row branch rechecks expiry, revocation, account
            // status and current role instead of trusting the route's old view.
            var current = AuthenticateSession(authorization)
                ?? throw new UnauthorizedAccessException("请先登录账号");
            if (administrator) EnsurePermission(current.Account, L12Permission.AdminAccountsRead);
            var targetId = administrator ? accountId : current.Account.Id;
            var account = targetId is null ? null : AccountById(targetId);
            if (account is null) throw new KeyNotFoundException("账号不存在");
            if (page < 1 || expectedRevision < 0 || page > 1 && expectedRevision is null)
                throw new ArgumentException("分页参数无效；后续页须携带当前信誉版本");
            pageSize = Math.Clamp(pageSize, 1, 50);
            var state = account.TournamentReputation;
            var revision = state?.Revision ?? 0;
            if (expectedRevision is { } expected && expected != revision)
                throw new L12TournamentVersionConflictException("信誉记录已更新，请从第一页重新读取");
            var now = DateTimeOffset.UtcNow;
            if (state is not null && now < state.ProjectedAt)
                throw new L12PlatformStorageUnavailableException("信誉事实时间尚未到达，当前分值暂不可用");
            var total = state?.Events.Count ?? 0;
            var pageEvents = new List<(TournamentReputationEventRow Event, int Sequence)>();
            var offset = ((long)page - 1) * pageSize;
            // Immutable append sequence breaks equal RecordedAt ties. No full
            // history sort/copy is needed merely to select this bounded page.
            for (var index = (long)total - 1 - offset; index >= 0 && pageEvents.Count < pageSize; index--)
                pageEvents.Add((state!.Events[(int)index], (int)index + 1));
            var requestedIds = pageEvents.Select(item => item.Event.Id).ToHashSet(StringComparer.Ordinal);
            var changes = new Dictionary<string, int>(StringComparer.Ordinal);
            var revoked = state?.Events.Where(item => item.Kind == "revoke").Select(item => item.RevokesEventId)
                .ToHashSet(StringComparer.Ordinal) ?? new HashSet<string?>(StringComparer.Ordinal);
            // This is the same authoritative per-account calculation used at
            // write/recovery, not a second scoring algorithm or a global scan.
            // Only requested page assessments are retained in the scratch map.
            var projected = ProjectTournamentReputation(state, now, changes, requestedIds);
            var committed = Volatile.Read(ref _committedSessionActivity);
            if (!committed.Available || committed.Revision != _data.Version
                || committed.CommittedTournaments is not { Available: true } tournaments)
                throw new L12PlatformStorageUnavailableException("信誉读取代际暂不可用");
            var items = pageEvents.Select(item =>
            {
                var entry = item.Event;
                if (!tournaments.TournamentsById.TryGetValue(entry.TournamentId, out var lookup)
                    || lookup.SourceOrder < 0 || lookup.SourceOrder >= _data.Tournaments.Count
                    || _data.Tournaments[lookup.SourceOrder].Id != entry.TournamentId)
                    throw new L12PlatformStorageUnavailableException("信誉赛事引用暂不可用");
                var isRevoked = revoked.Contains(entry.Id);
                var delta = changes.GetValueOrDefault(entry.Id);
                var assessment = entry.Kind == "revoke" ? "correction" : isRevoked ? "revoked"
                    : entry.Exemption is not null ? "exempt" : delta < 0 ? "deducted" : "no-additional-deduction";
                return new L12TournamentReputationHistoryItemView(entry.Id, item.Sequence, entry.TournamentId,
                    _data.Tournaments[lookup.SourceOrder].Name, entry.Kind, entry.EffectiveAt, entry.RecordedAt,
                    assessment, entry.Kind == "revoke" ? null : delta, entry.RevokesEventId, entry.Exemption);
            }).ToArray();
            return new(TournamentReputationRuleVersion, projected.Score,
                projected.Score < 60 ? "blocked" : projected.Score < 80 ? "warning" : "normal",
                now, revision, projected.NextRecoveryAt, page, pageSize, total, items);
        }
    }

    internal T ExecuteAuthorizedTournamentReputationRevoke<T>(string? authorization, Func<L12AccountView, T> action)
        => ExecuteAdminTransaction(() =>
        {
            // Revalidate even command replay within the original transaction lock.
            var current = AuthenticateSession(authorization)
                ?? throw new UnauthorizedAccessException("请先登录账号");
            EnsurePermission(current.Account, L12Permission.AdminAccountStatusWrite);
            return action(current.Account);
        });

    private (L12AccountView Actor, AccountRow Account, TournamentRow Tournament, TournamentReputationEventRow Original)
        RequireTournamentReputationCorrection(string? authorization, string accountId, string eventId, string reason)
    {
        var current = AuthenticateSession(authorization)
            ?? throw new UnauthorizedAccessException("请先登录账号");
        EnsurePermission(current.Account, L12Permission.AdminAccountStatusWrite);
        RequireText(reason, "撤销原因", 500);
        if (current.Account.Id == accountId)
            throw new L12TournamentScopeException("不能纠正本人的信誉，请由其他无利益冲突的管理员处理");
        var account = AccountById(accountId) ?? throw new KeyNotFoundException("账号不存在");
        var original = account.TournamentReputation?.Events.FirstOrDefault(item => item.Id == eventId)
            ?? throw new KeyNotFoundException("原信誉事实不存在");
        if (original.Kind is not ("withdrawal" or "no-show") || original.Penalty <= 0 || original.Exemption is not null)
            throw new ArgumentException("只能撤销原有效处置，不能撤销纠正或免责记录");
        var tournament = _data.Tournaments.FirstOrDefault(item => item.Id == original.TournamentId)
            ?? throw new KeyNotFoundException("原事实所属赛事不存在");
        if (tournament.ReputationRuleVersion != TournamentReputationRuleVersion)
            throw new ArgumentException("历史赛事不适用信誉纠正");
        if (original.Source?.MatchId is { Length: > 0 } matchId)
            RequireIndependentMatchStaff(current.Account.Id, RequireMatch(tournament, matchId).Match);
        return (current.Account, account, tournament, original);
    }

    internal L12TournamentReputationRevokePreview PreviewAccountTournamentReputationRevoke(string? authorization,
        string accountId, string eventId, string reason, long expectedReputationRevision)
    {
        lock (_gate)
        {
            var (actor, account, tournament, original) = RequireTournamentReputationCorrection(authorization, accountId, eventId, reason);
            var now = DateTimeOffset.UtcNow;
            var before = ProjectTournamentReputation(account.TournamentReputation, now);
            if (before.Revision != expectedReputationRevision)
                throw new L12TournamentVersionConflictException("信誉记录已变化，请刷新后重新预演");
            var result = RecordTournamentReputationFactCore(actor,
                new(Guid.NewGuid().ToString("N"), tournament.Id, accountId, "revoke", now, original.Id),
                tournament, expectedReputationRevision,
                new("reputation-revoke-preview", Reason: reason, DryRun: true), false, now);
            static L12TournamentReputationCorrectionProjection View(L12TournamentReputationProjection value)
                => new(value.Score, value.LastViolationAt, value.NextRecoveryAt);
            return new(accountId, eventId, tournament.Id, tournament.Version, _data.Version, before.Revision,
                result.AlreadyApplied, View(before), View(result.Projection));
        }
    }

    internal L12TournamentReputationRevokeResult RevokeAccountTournamentReputation(string? authorization,
        L12TournamentReputationRevokePayload payload, L12AdminAuditContext audit)
        => ExecuteAdminTransaction<L12TournamentReputationRevokeResult>(() =>
        {
            var (actor, account, tournament, original) = RequireTournamentReputationCorrection(authorization,
                payload.AccountId, payload.EventId, payload.Reason);
            if (audit.ExpectedVersion is not { } platformVersion || platformVersion != _data.Version
                || tournament.Version != payload.ExpectedTournamentVersion
                || (account.TournamentReputation?.Revision ?? 0) != payload.ExpectedReputationRevision)
                throw new L12TournamentVersionConflictException("账号、赛事或信誉版本已变化，请重新预演");
            var now = DateTimeOffset.UtcNow;
            var result = RecordTournamentReputationFactCore(actor,
                new(Guid.NewGuid().ToString("N"), tournament.Id, payload.AccountId, "revoke", now, original.Id),
                tournament, payload.ExpectedReputationRevision, audit with { Reason = payload.Reason }, true, now);
            return new(result.Applied, result.AlreadyApplied, result.Projection.Score,
                result.Projection.Revision, result.Projection.NextRecoveryAt);
        });

    internal L12TournamentReputationOperation RecordTournamentReputationFact(L12AccountView actor,
        L12TournamentReputationFact fact, long expectedTournamentVersion, long expectedReputationRevision,
        L12AdminAuditContext audit, bool apply, DateTimeOffset utcNow)
    {
        EnsurePermission(actor, L12Permission.AdminAccountStatusWrite);
        return ExecuteAdminTransaction(() => RecordTournamentReputationFactCore(actor, fact,
            RequireTournament(fact.TournamentId, expectedTournamentVersion), expectedReputationRevision,
            audit, apply, utcNow));
    }

    private L12TournamentReputationOperation RecordTournamentReputationFactCore(L12AccountView actor,
        L12TournamentReputationFact fact, TournamentRow tournament, long expectedReputationRevision,
        L12AdminAuditContext audit, bool apply, DateTimeOffset utcNow,
        TournamentReputationSource? source = null, bool save = true)
    {
            var now = utcNow.ToUniversalTime();
            var account = AccountById(fact.AccountId) ?? throw new KeyNotFoundException("账号不存在");
            var before = account.TournamentReputation;
            var projection = ProjectTournamentReputation(before, now);
            if (tournament.ReputationRuleVersion != TournamentReputationRuleVersion)
                return new L12TournamentReputationOperation(false, false, "legacy-tournament", projection);
            if (string.IsNullOrWhiteSpace(fact.Id) || fact.Id.Length > 160 || fact.EffectiveAt == default
                || fact.EffectiveAt > now || fact.Kind is not ("withdrawal" or "no-show" or "revoke")
                || (fact.Kind == "revoke") != (fact.RevokesEventId is not null))
                throw new ArgumentException("赛事信誉事实无效");
            if (before?.Events.FirstOrDefault(item => item.Id == fact.Id) is { } prior)
            {
                if (prior.TournamentId != fact.TournamentId || prior.Kind != fact.Kind
                    || prior.EffectiveAt != fact.EffectiveAt || prior.RevokesEventId != fact.RevokesEventId)
                    throw new L12TournamentVersionConflictException("相同信誉事实身份的内容不同");
                return new L12TournamentReputationOperation(false, true, prior.Exemption, projection);
            }
            if ((before?.Revision ?? 0) != expectedReputationRevision)
                throw new L12TournamentVersionConflictException("赛事信誉已更新，请刷新后重试");
            if (before is not null && now < before.ProjectedAt)
                throw new ArgumentException("信誉记录时间不能倒退");
            var participant = tournament.Participants.FirstOrDefault(item => item.AccountId == fact.AccountId)
                ?? throw new KeyNotFoundException("尚未报名该赛事");
            string? exemption = null;
            var penalty = 0;
            if (fact.Kind == "revoke")
            {
                if (before?.Events.SingleOrDefault(item => item.Id == fact.RevokesEventId
                        && item.TournamentId == fact.TournamentId && item.Kind != "revoke") is not { } original
                    || fact.EffectiveAt < original.RecordedAt)
                    throw new ArgumentException("撤销必须引用本账号本赛事已存在的原事实");
                if (before.Events.Any(item => item.RevokesEventId == original.Id))
                    return new L12TournamentReputationOperation(false, true, "already-revoked", projection);
            }
            else
            {
                if (!(source?.FormalSeat ?? !participant.Waitlisted)) exemption = "unpromoted-waitlist";
                else if (tournament.CanceledAt is not null) exemption = "organizer-cancelled";
                else if (tournament.CheckInStart is not { } start || fact.EffectiveAt < start.EffectiveAt)
                    exemption = "before-check-in";
                else if (fact.Kind == "withdrawal" && tournament.Postponements.Any(item =>
                             item.CreatedAt >= start.EffectiveAt && item.CreatedAt <= fact.EffectiveAt
                             && fact.EffectiveAt < item.NewStartAt)) exemption = "organizer-postponed";
                else penalty = fact.Kind == "withdrawal" ? 10 : 20;
            }
            var candidate = new TournamentReputationStateRow
            {
                Revision = (before?.Revision ?? 0) + 1,
                Events = before is null ? [] : [.. before.Events],
            };
            candidate.Events.Add(new(fact.Id, fact.TournamentId, TournamentReputationRuleVersion,
                fact.Kind, fact.EffectiveAt.ToUniversalTime(), now, penalty, source?.FormalSeat ?? !participant.Waitlisted,
                source?.CheckInStartedAt ?? tournament.CheckInStart?.EffectiveAt, exemption, fact.RevokesEventId, actor.Id,
                string.IsNullOrWhiteSpace(audit.CorrelationId) ? $"reputation:{fact.Id}" : audit.CorrelationId, source));
            var after = ProjectTournamentReputation(candidate, now);
            candidate.Score = after.Score; candidate.ProjectedAt = now;
            candidate.LastViolationAt = after.LastViolationAt; candidate.NextRecoveryAt = after.NextRecoveryAt;
            if (!apply) return new L12TournamentReputationOperation(false, false, exemption, after);
            account.TournamentReputation = candidate;
            AddAdminAudit(actor, "account", "tournament-reputation-fact", $"account:{account.Id}",
                null, fact.Id, fact.Kind, audit);
            if (save) Save();
            return new L12TournamentReputationOperation(true, false, exemption, after);
    }

    private void ApplyTournamentReputationTransition(L12AccountView actor, TournamentRow before,
        TournamentRow after, string action, string target, L12AdminAuditContext audit, DateTimeOffset now)
    {
        if (after.ReputationRuleVersion != TournamentReputationRuleVersion
            || action is not ("drop" or "start" or "ruling" or "late-grace-settlement" or "attention-required" or "cancel")) return;
        var previousParticipants = before.Participants.ToDictionary(item => item.AccountId, StringComparer.Ordinal);
        void Record(string accountId, string kind, string root, DateTimeOffset effectiveAt,
            string sourceKind, string? matchId = null, int? round = null, DateTimeOffset? deadline = null,
            string? revokes = null)
        {
            if (!previousParticipants.TryGetValue(accountId, out var original)) return;
            var source = new TournamentReputationSource(!original.Waitlisted && !original.Removed && !original.Dropped,
                after.CheckInStart?.EffectiveAt, root, sourceKind, matchId, round, deadline);
            var account = AccountById(accountId) ?? throw new KeyNotFoundException("信誉事实账号不存在");
            var fact = new L12TournamentReputationFact($"rp:{Hash(root + ":" + accountId)}", after.Id,
                accountId, kind, effectiveAt, revokes);
            RecordTournamentReputationFactCore(actor, fact, after, account.TournamentReputation?.Revision ?? 0,
                audit, true, now, source, save: false);
        }

        if (action == "drop" && previousParticipants.TryGetValue(target, out var withdrawing)
            && !withdrawing.Dropped && !withdrawing.Removed)
            Record(target, "withdrawal", $"{before.Id}:drop:{before.Version + 1}:{target}", now, "withdrawal");

        if (before.Status == "registration" && after.Status == "running")
            foreach (var participant in before.Participants.Where(item => !item.Dropped && !item.Removed
                         && !item.Waitlisted && item.TournamentCheckedInAt is null))
                Record(participant.AccountId, "no-show", $"{before.Id}:start:{participant.AccountId}", now,
                    "registration-no-show");

        foreach (var oldRound in before.Rounds.Where(item => item.Status != "completed"))
        foreach (var oldMatch in oldRound.Matches)
        {
            if (oldMatch.GraceDeadline is not { } deadline || deadline > now || oldMatch.Status == "completed") continue;
            var next = after.Rounds.FirstOrDefault(item => item.Id == oldRound.Id)?.Matches
                .FirstOrDefault(item => item.Id == oldMatch.Id);
            if (next is null) continue;
            var events = next.Events.Skip(oldMatch.Events.Count).ToArray();
            var rulings = next.Rulings.Skip(oldMatch.Rulings.Count).ToArray();
            var absentA = !oldMatch.ReadyA && (events.Any(item => item.Kind == "double-no-show"
                    || item.Kind == "no-show" && item.Result == "no-show-a")
                || rulings.Any(item => item.Kind == "no-show" && item.Decision == "no-show-a"));
            var absentB = !oldMatch.ReadyB && (events.Any(item => item.Kind == "double-no-show"
                    || item.Kind == "no-show" && item.Result == "no-show-b")
                || rulings.Any(item => item.Kind == "no-show" && item.Decision == "no-show-b"));
            void RecordAbsent(string accountId)
            {
                if (!previousParticipants.TryGetValue(accountId, out var participant)
                    || participant.Dropped || participant.Removed || participant.Waitlisted) return;
                Record(accountId, "no-show", $"{before.Id}:{oldMatch.Id}:grace:{deadline.UtcTicks}:{accountId}",
                    deadline, "round-grace", oldMatch.Id, oldRound.Number, deadline);
            }
            if (absentA) RecordAbsent(oldMatch.PlayerAAccountId);
            if (absentB && oldMatch.PlayerBAccountId is { } second) RecordAbsent(second);
        }

        if (before.Status != "canceled" && after.Status == "canceled")
            foreach (var participant in before.Participants)
            {
                var state = AccountById(participant.AccountId)?.TournamentReputation;
                if (state is null) continue;
                var revoked = state.Events.Where(item => item.RevokesEventId is not null)
                    .Select(item => item.RevokesEventId).ToHashSet(StringComparer.Ordinal);
                foreach (var original in state.Events.Where(item => item.TournamentId == before.Id
                             && item.Penalty > 0 && !revoked.Contains(item.Id)).ToArray())
                    Record(participant.AccountId, "revoke", $"{before.Id}:cancel:{original.Id}", now,
                        "cancel-revoke", revokes: original.Id);
            }
    }

    private static L12TournamentReputationProjection ProjectTournamentReputation(
        TournamentReputationStateRow? state, DateTimeOffset asOf,
        Dictionary<string, int>? scoreChanges = null, HashSet<string>? requestedIds = null)
    {
        if (state is null) return new(100, 0, asOf, null, null);
        var visible = state.Events.Where(item => item.RecordedAt <= asOf).ToArray();
        var revoked = visible.Where(item => item.Kind == "revoke").Select(item => item.RevokesEventId)
            .ToHashSet(StringComparer.Ordinal);
        var penalties = new Dictionary<string, int>(StringComparer.Ordinal);
        var score = 100;
        DateTimeOffset? anchor = null, lastViolation = null;
        void Recover(DateTimeOffset until)
        {
            if (anchor is not { } from || until < from) return;
            var periods = (until - from).Ticks / TournamentReputationRecoveryPeriod.Ticks;
            score += (int)Math.Min(100 - score, periods * 5);
            anchor = from.AddTicks(periods * TournamentReputationRecoveryPeriod.Ticks);
        }
        foreach (var entry in visible.Where(item => item.Penalty > 0 && !revoked.Contains(item.Id))
                     .OrderBy(item => item.EffectiveAt).ThenBy(item => item.Id, StringComparer.Ordinal))
        {
            var oldPenalty = penalties.GetValueOrDefault(entry.TournamentId);
            Recover(entry.EffectiveAt);
            var beforePenalty = score;
            score = Math.Max(0, score - Math.Max(0, entry.Penalty - oldPenalty));
            if (scoreChanges is not null && (requestedIds is null || requestedIds.Contains(entry.Id)))
                scoreChanges[entry.Id] = score - beforePenalty;
            penalties[entry.TournamentId] = Math.Max(oldPenalty, entry.Penalty);
            // A distinct effective violation restarts the clean period even
            // when this tournament's deduction has already reached its cap.
            anchor = lastViolation = entry.EffectiveAt;
        }
        Recover(asOf);
        return new(score, state.Revision, asOf, lastViolation,
            score < 100 && anchor is { } recoveryFrom ? recoveryFrom + TournamentReputationRecoveryPeriod : null);
    }

    private static void ValidateTournamentReputation(DataFile data)
    {
        var referencedIds = new HashSet<string>(StringComparer.Ordinal);
        foreach (var account in data.Accounts)
        {
            if (account.TournamentReputation is not { } state) continue;
            if (state.Events is null)
                throw new L12PlatformStorageIncompatibleException("账号赛事信誉事件集合无效");
            foreach (var entry in state.Events)
            {
                if (entry is null || entry.TournamentId is null)
                    throw new L12PlatformStorageIncompatibleException("账号赛事信誉事件无效");
                referencedIds.Add(entry.TournamentId);
            }
        }
        var referenced = new Dictionary<string, (TournamentRow Row, HashSet<string> Seats)>(StringComparer.Ordinal);
        var graceMatches = new Dictionary<string, Dictionary<string, int>>(StringComparer.Ordinal);
        foreach (var tournament in data.Tournaments)
        {
            // Reuse the mandatory timing-validation pass. Empty ledgers do not
            // allocate participant indexes or add another tournament scan.
            if (referencedIds.Contains(tournament.Id) && !referenced.ContainsKey(tournament.Id))
                referenced.Add(tournament.Id, (tournament, tournament.Participants.Select(item => item.AccountId)
                    .ToHashSet(StringComparer.Ordinal)));
            if (tournament.ReputationRuleVersion is not (0 or TournamentReputationRuleVersion)
                || tournament.CheckInPlans is null)
                throw new L12PlatformStorageIncompatibleException("赛事信誉策略或计划无效");
            if (tournament.ReputationRuleVersion == 0)
            {
                if (tournament.CheckInPlans.Count != 0 || tournament.CheckInStart is not null)
                    throw new L12PlatformStorageIncompatibleException("旧赛事不能包含信誉签到事实");
                continue;
            }
            if (tournament.LegacySourceId is not null || tournament.CheckInPlans.Count == 0)
                throw new L12PlatformStorageIncompatibleException("新赛事信誉策略来源无效");
            DateTimeOffset previousAt = default;
            for (var index = 0; index < tournament.CheckInPlans.Count; index++)
            {
                var plan = tournament.CheckInPlans[index];
                var expected = plan.StartAt?.AddMinutes(-plan.CheckInMinutes);
                if (expected < plan.RecordedAt) expected = plan.RecordedAt;
                if (plan.Revision != index + 1 || plan.RecordedAt == default || plan.RecordedAt < previousAt
                    || plan.CheckInMinutes is < 1 or > 60 || plan.OpensAt != expected
                    || string.IsNullOrWhiteSpace(plan.ActorId) || string.IsNullOrWhiteSpace(plan.CorrelationId))
                    throw new L12PlatformStorageIncompatibleException("赛事签到计划事实无效");
                previousAt = plan.RecordedAt;
            }
            var last = tournament.CheckInPlans[^1];
            if (last.StartAt != tournament.StartAt || last.CheckInMinutes != tournament.CheckInMinutes)
                throw new L12PlatformStorageIncompatibleException("赛事当前计划与签到计划事实不一致");
            if (tournament.CheckInStart is { } start)
            {
                var plan = tournament.CheckInPlans.SingleOrDefault(item => item.Revision == start.PlanRevision);
                if (plan is null || start.EffectiveAt < plan.RecordedAt || start.RecordedAt < start.EffectiveAt
                    || start.Source is not ("scheduled" or "manual" or "manual-start" or "automatic-start")
                    || start.Source == "scheduled" && start.EffectiveAt != plan.OpensAt
                    || start.Source != "scheduled" && (start.EffectiveAt != start.RecordedAt
                        || string.IsNullOrWhiteSpace(start.ActorId))
                    || string.IsNullOrWhiteSpace(start.CorrelationId))
                    throw new L12PlatformStorageIncompatibleException("赛事签到开始事实无效");
            }
        }
        foreach (var account in data.Accounts)
        {
            if (account.TournamentReputation is not { } state) continue;
            if (state.RuleVersion != TournamentReputationRuleVersion || state.Events is null
                || state.Events.Count == 0 || state.Revision != state.Events.Count || state.ProjectedAt == default)
                throw new L12PlatformStorageIncompatibleException("账号赛事信誉账版本无效");
            var byId = new Dictionary<string, TournamentReputationEventRow>(StringComparer.Ordinal);
            var revokedTargets = new HashSet<string>(StringComparer.Ordinal);
            DateTimeOffset previousAt = default;
            foreach (var entry in state.Events)
            {
                referenced.TryGetValue(entry.TournamentId, out var source);
                var tournament = source.Row;
                if (string.IsNullOrWhiteSpace(entry.Id) || !byId.TryAdd(entry.Id, entry)
                    || tournament?.ReputationRuleVersion != entry.RuleVersion || entry.RuleVersion != TournamentReputationRuleVersion
                    || !source.Seats.Contains(account.Id)
                    || entry.EffectiveAt == default || entry.RecordedAt < entry.EffectiveAt
                    || entry.RecordedAt < previousAt || entry.RecordedAt > state.ProjectedAt
                    || string.IsNullOrWhiteSpace(entry.ActorId) || string.IsNullOrWhiteSpace(entry.CorrelationId)
                    || entry.Kind is not ("withdrawal" or "no-show" or "revoke")
                    || entry.Exemption is not (null or "unpromoted-waitlist" or "organizer-cancelled"
                        or "before-check-in" or "organizer-postponed")
                    || (entry.Kind == "revoke") != (entry.RevokesEventId is not null)
                    || entry.Penalty > 0 && (!entry.FormalSeat || entry.CheckInStartedAt is null
                        || entry.CheckInStartedAt != tournament.CheckInStart?.EffectiveAt
                        || entry.EffectiveAt < entry.CheckInStartedAt)
                    || entry.Penalty != (entry.Kind == "revoke" || entry.Exemption is not null ? 0
                        : entry.Kind == "withdrawal" ? 10 : 20))
                    throw new L12PlatformStorageIncompatibleException("账号赛事信誉事件无效");
                if (entry.RevokesEventId is { } revoked && (!byId.TryGetValue(revoked, out var original)
                    || original.Kind == "revoke" || original.TournamentId != entry.TournamentId
                    || entry.EffectiveAt < original.RecordedAt
                    || !revokedTargets.Add(revoked)))
                    throw new L12PlatformStorageIncompatibleException("赛事信誉撤销归属无效");
                if (entry.Source is { } sourceFact)
                {
                    if (string.IsNullOrWhiteSpace(sourceFact.RootId)
                        || entry.Id != $"rp:{Hash(sourceFact.RootId + ":" + account.Id)}"
                        || sourceFact.FormalSeat != entry.FormalSeat
                        || sourceFact.CheckInStartedAt != entry.CheckInStartedAt
                        || sourceFact.Kind is not ("withdrawal" or "registration-no-show" or "round-grace" or "cancel-revoke")
                        || sourceFact.Kind == "withdrawal" && entry.Kind != "withdrawal"
                        || sourceFact.Kind is "registration-no-show" or "round-grace" && entry.Kind != "no-show"
                        || sourceFact.Kind == "cancel-revoke" && entry.Kind != "revoke")
                        throw new L12PlatformStorageIncompatibleException("赛事信誉原始事实身份无效");
                    if (sourceFact.Kind == "round-grace")
                    {
                        if (!graceMatches.TryGetValue(entry.TournamentId, out var matches))
                        {
                            matches = new(StringComparer.Ordinal);
                            foreach (var round in tournament.Rounds)
                            foreach (var match in round.Matches) matches.TryAdd(match.Id, round.Number);
                            graceMatches.Add(entry.TournamentId, matches);
                        }
                        if (sourceFact.MatchId is null || !matches.TryGetValue(sourceFact.MatchId, out var roundNumber)
                            || sourceFact.Round != roundNumber || sourceFact.Deadline != entry.EffectiveAt)
                            throw new L12PlatformStorageIncompatibleException("赛事宽限缺席事实归属无效");
                    }
                    else if (sourceFact.MatchId is not null || sourceFact.Round is not null || sourceFact.Deadline is not null)
                        throw new L12PlatformStorageIncompatibleException("非桌次信誉事实包含错误桌次归属");
                }
                previousAt = entry.RecordedAt;
            }
            var computed = ProjectTournamentReputation(state, state.ProjectedAt);
            if (state.Score != computed.Score || state.LastViolationAt != computed.LastViolationAt
                || state.NextRecoveryAt != computed.NextRecoveryAt)
                throw new L12PlatformStorageIncompatibleException("赛事信誉账与核算投影不一致");
        }
    }
}
